ROOT=Path(__file__).resolve().parent
M=json.loads((ROOT/'results/metrics.json').read_text(encoding='utf-8'))
font='C:/Windows/Fonts/arial.ttf'; bold='C:/Windows/Fonts/arialbd.ttf'
pdfmetrics.registerFont(TTFont('Arial',font)); pdfmetrics.registerFont(TTFont('Arial-Bold',bold))
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='TitleVN',fontName='Arial-Bold',fontSize=22,leading=26,textColor=colors.HexColor('#15324B'),spaceAfter=6)); styles.add(ParagraphStyle(name='H1VN',fontName='Arial-Bold',fontSize=15,leading=18,textColor=colors.HexColor('#15324B'),spaceBefore=5,spaceAfter=6)); styles.add(ParagraphStyle(name='H2VN',fontName='Arial-Bold',fontSize=11,leading=13,textColor=colors.HexColor('#286A8A'),spaceBefore=4,spaceAfter=3)); styles.add(ParagraphStyle(name='BodyVN',fontName='Arial',fontSize=8.7,leading=11.5,textColor=colors.HexColor('#28303A'),spaceAfter=5)); styles.add(ParagraphStyle(name='SmallVN',fontName='Arial',fontSize=7.5,leading=9,textColor=colors.HexColor('#5F6973'),alignment=TA_CENTER,spaceAfter=4)); styles.add(ParagraphStyle(name='CellVN',fontName='Arial',fontSize=7.5,leading=9)); styles.add(ParagraphStyle(name='CellHeadVN',fontName='Arial-Bold',fontSize=7.5,leading=9,textColor=colors.white))
def P(txt,style='BodyVN'): return Paragraph(txt,styles[style])
def T(headers,rows,widths=None):
    data=[[P(str(x),'CellHeadVN') for x in headers]]+[[x if hasattr(x,'drawOn') else P(str(x),'CellVN') for x in row] for row in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='CENTER')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#15324B')),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#CCD5DD')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F3F6F8')]),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return t
def fig(name,w): return Image(str(ROOT/'results/figures'/name),width=w*inch,height=w*inch*ImageReader(str(ROOT/'results/figures'/name)).getSize()[1]/ImageReader(str(ROOT/'results/figures'/name)).getSize()[0])
def footer(canvas,doc):
    canvas.saveState(); canvas.setFont('Arial',7); canvas.setFillColor(colors.HexColor('#687782')); canvas.drawString(.65*inch,.35*inch,'CSE457 | Lab 3 Gaussian HMM'); canvas.drawRightString(7.85*inch,.35*inch,str(doc.page)); canvas.restoreState()
story=[]
story += [P('Lab 3 Nhận dạng tiếng nói với HMM','TitleVN'),P('Báo cáo thực hành | CSE457 - Xử lý âm thanh và tiếng nói')]
story += [P('Mục tiêu là xây dựng bộ nhận dạng 5 lệnh bằng Gaussian HMM trái-sang-phải, quan sát likelihood và Viterbi, rồi so sánh với DTW và thử mở rộng bằng lexicon cùng bigram. Kết quả trên test sạch đạt 100% cho cả HMM và DTW; kiểm tra nhiễu 20 dB giảm còn 60%, cho thấy độ nhạy môi trường rõ hơn mức accuracy sạch thể hiện.'),P('1. Dữ liệu và quy trình','H1VN')]
story += [P('Repository có bảy lệnh, mỗi lớp năm bản ghi. Bài dùng bat, dung, len, xuong, trai; files 01-03 là train và 04-05 là test, tổng cộng 15/10 utterance. Không có file nào xuất hiện ở cả hai split. Dữ liệu ít hơn đề xuất 6 train + 2 test mỗi lớp và chỉ đại diện một điều kiện ghi âm.'),P('WAV mono 16 kHz, trim silence, pre-emphasis 0.97. Front-end dùng 13 MFCC với cửa sổ Hamming 25 ms và hop 10 ms; delta/delta-delta được nối thành T×39. CMVN tính riêng từng utterance. Sai phân bổ sung thông tin chuyển động phổ theo thời gian.')]
story += [fig('features_bat.png',5.8),P('Hình 1. MFCC, delta và delta-delta của utterance bat.','SmallVN'),P('2. Gaussian HMM và huấn luyện','H1VN')]
story += [P('Mỗi lớp có một whole-word HMM. π bắt đầu ở state 0; mỗi hàng chuyển tiếp chỉ cho phép self-loop và next-state, state cuối tự lặp. Xác suất phát xạ là Gaussian diagonal. Với ít dữ liệu và 39 chiều, diagonal cần ít tham số hơn covariance đầy đủ (39 so với 780 phần tử covariance mỗi state), giảm ước lượng không ổn định. Các transition cấm giữ bằng 0 trong Baum-Welch.'),P('Mã NumPy/SciPy tính log-domain Forward-Backward, gamma_t(i) và xi_t(i,j), rồi cập nhật tham số bằng EM. Likelihood Forward cộng xác suất mọi đường state; Viterbi thay tổng bằng max và lưu backpointer. Forward trả likelihood của chuỗi quan sát; Viterbi trả đường state tốt nhất.')]
story += [T(['Số state','Test accuracy','Vòng lặp EM TB'],[[x['n_states'],f"{x['accuracy']:.0%}",f"{x['mean_iterations']:.1f}"] for x in M['state_experiment']],[1.5*inch,1.5*inch,1.5*inch]),Spacer(1,5),P('Cả 3, 5 và 7 state đều đúng 10/10 mẫu; tập test quá nhỏ để kết luận cấu hình nào tổng quát tốt hơn. Dùng 5 state theo case study. Baum-Welch có thể dừng ở cực đại cục bộ do khởi tạo, quá ít token, quá nhiều state hoặc covariance suy biến.')]
story += [PageBreak(),P('3. Nhận dạng và Viterbi alignment','H1VN'),P('Quy tắc ML chọn lớp có log P(X|λ) cao nhất. Với cùng utterance, chia score cho số frame không đổi thứ hạng; score/frame hữu ích khi đặt ngưỡng reject giữa utterance độ dài khác nhau. Ví dụ test bat_04:')]
with (ROOT/'results/hmm_test_scores.csv').open(encoding='utf-8') as f: row=next(r for r in csv.DictReader(f) if r['file']=='bat_04.wav')
story += [T(['Model','log-likelihood'],[[w,f"{float(row['score_'+w]):.1f}"] for w in M['labels']],[2.1*inch,2.1*inch]),P(f"bat_04 được nhận là {row['top1']} vì score cao nhất; top-1/top-2 cách nhau {float(row['margin']):.1f} log units. Khoảng cách lớn thể hiện các lớp tách biệt trong tập nhỏ, không phải ngưỡng unknown đã kiểm định."),T(['HMM confusion matrix','DTW confusion matrix'],[[fig('hmm_confusion.png',2.35),fig('dtw_confusion.png',2.35)]],[3.25*inch,3.25*inch]),P('Hình 2-3. Cùng 10 test utterance: cả hai ma trận đều có 2/2 đúng mỗi lớp.','SmallVN'),P('Viterbi paths sau đây không giảm theo frame, đúng topology left-to-right. Thời gian ở state là số frame liên tiếp × 10 ms; state trong word HMM không đồng nghĩa với phoneme nếu không có giám sát phone.')]
story += [T(['bat_04 alignment','xuong_04 alignment'],[[fig('viterbi_bat_04.png',2.7),fig('viterbi_xuong_04.png',2.7)]],[3.25*inch,3.25*inch]),P('Hình 4-5. State index theo frame trên hai utterance.','SmallVN'),P('4. DTW và robustness','H1VN')]
story += [T(['Phương pháp','Đặc trưng','Accuracy','Train/lớp','Test/trial'],[['Gaussian HMM','39D MFCC động','100%','3',f"{M['mean_hmm_test_decode_seconds']*1000:.2f} ms"],['DTW','13D MFCC tĩnh','100%','3 template',f"{M['mean_dtw_test_seconds']*1000:.2f} ms"]])]
story += [P('Hai phương pháp ngang accuracy trên split nhỏ. DTW có warping path trực tiếp, phù hợp số template ít; HMM học phân bố trạng thái và mở rộng sang phone, lexicon, LM nhưng cần dữ liệu để ước lượng ổn định. Thời gian là phép đo tham khảo, không benchmark chuẩn hóa. Static MFCC HMM cũng đạt 100%, nên bộ này chưa chứng minh delta tăng accuracy. Nhiễu trắng tổng hợp 20 dB làm accuracy còn 60% (6/10); đây là mismatch noise, không phải người nói mới. Không fit full covariance vì ba utterance train/lớp là quá ít cho 39 chiều.')]
story += [PageBreak(),P('5. Lexicon, bigram và MAP re-ranking','H1VN'),P('Whole-word HMM không cần lexicon. Khi dùng phone/subword HMM, lexicon ánh xạ từ thành chuỗi phone để ghép phone model thành word network. `lexicon.txt` minh họa định dạng và parser tạo dictionary; các phone phải thay bằng inventory giảng viên cung cấp.'),P('Corpus lệnh ngắn minh họa unigram/bigram. Add-k: P(w|prev)=(C(prev,w)+k)/(C(prev)+kV), k=0.5. Điểm re-ranking = log-likelihood/frame + λ log P(w|prev). Sweep λ=0, 0.1, 0.3, 1 và 100. Với test có margin nhỏ nhất, các candidate thật vẫn cách nhau lớn; λ≤1 giữ quyết định acoustic, λ=100 đổi sang trái dù acoustic chọn bat. Điều này minh họa prior quá mạnh có thể áp đảo âm học. Corpus không đại diện ngôn ngữ tự nhiên, chỉ dùng sư phạm.')]
story += [P('6. Câu hỏi phân tích','H1VN')]
for q,a in [
('gamma_t và xi_t trong EM','gamma_t(i) là mức trách nhiệm của state i cho frame t; xi_t(i,j) là trách nhiệm của chuyển i->j. E-step tính hai đại lượng, M-step dùng làm trọng số cập nhật.'),
('Vì sao covariance diagonal?','Giảm mạnh số tham số và tránh ước lượng ma trận đầy đủ không ổn định khi dữ liệu ít, số chiều cao.'),
('Delta features hữu ích thế nào?','Đưa vận tốc/gia tốc biến thiên phổ vào vector frame; emission độc lập có điều kiện không tự mô tả tương quan cục bộ.'),
('Self-loop khi nói chậm?','Cho phép state giữ lâu hơn, hấp thụ duration thay đổi mà không cần cố định frame mỗi state.'),
('Khi cần lexicon?','Không cần cho word HMM; cần khi giải mã bằng phone/subword HMM.'),
('DTW path và Viterbi path?','DTW căn chỉnh hai chuỗi feature bằng đường chi phí nhỏ; Viterbi tìm state sequence tốt nhất theo xác suất transition/emission.'),
('Unknown/reject?','Argmax luôn trả lớp. Từ chối khi log-likelihood/frame thấp hoặc margin top1-top2 nhỏ; hiệu chỉnh ngưỡng bằng validation chứa unknown.')]: story.append(P('<b>'+q+':</b> '+a))
story += [P('Ba nguyên nhân nghiệm EM xấu: khởi tạo state/emission không phù hợp; ít token so với số tham số; số state/covariance quá phức tạp dẫn tới variance gần 0. Nhiễu, kênh khác và split sai cũng làm test giảm dù EM hội tụ.')]
story += [P('7. Kết luận và giới hạn','H1VN'),P('Pipeline hoàn thành MFCC động, HMM, likelihood/Viterbi, confusion matrix, DTW, sweep state, robustness, lexicon parser và bigram re-ranking. Accuracy sạch 100% chỉ dựa trên 10 test file; noise làm giảm 40 điểm phần trăm. Cần thêm ít nhất 6 train + 2 test mỗi lớp, người nói và điều kiện ghi âm khác, cùng phone inventory/corpus thật của lớp.'),P('Tái lập: chạy `python lab3.py` từ thư mục LAB3. Mã, notebook, split, model archives, bảng và biểu đồ được lưu cạnh báo cáo.')]
doc=SimpleDocTemplate(str(ROOT/'Bao_cao_Lab3.pdf'),pagesize=letter,rightMargin=.58*inch,leftMargin=.58*inch,topMargin=.5*inch,bottomMargin=.55*inch,title='Lab 3 Nhận dạng tiếng nói với HMM',author='CSE457 Lab')
